--
-- Name: p_sales_generate(integer); Type: PROCEDURE; Schema: sequel-mart-schema; Owner: postgres
--

CREATE PROCEDURE "sequel-mart-schema".p_sales_generate(IN sales integer)
    LANGUAGE plpgsql
    AS $$
DECLARE customer_total smallint;

DECLARE transaction_no int;
DECLARE transaction_lines smallint;
DECLARE items_sold smallint;

DECLARE product_line smallint;
DECLARE product_price money;
DECLARE product_cost money;

DECLARE sale_date timestamp;
DECLARE sale_date_id integer;

DECLARE random_date decimal(18,12);
DECLARE random_product_popularity decimal(9,2);
DECLARE random_feedback numeric(9,2);
DECLARE feedback_score numeric(9,2);
BEGIN

	customer_total = COUNT(1)-1 AS customer_total FROM "sequel-mart-schema"."Customers";

	--Iterate through the number of sales we want to generate (specified above) and generate a sales transaction
	FOR i IN 1..sales LOOP
		
		--Generate a random sales date within the last ~8 months (330,000 minutes)
		random_date = RANDOM() * 330000;
		sale_date = CURRENT_TIMESTAMP - (random_date * interval '1 minute');
		sale_date_id = CONCAT(EXTRACT(YEAR FROM sale_date),TO_CHAR(sale_date,'MM'),TO_CHAR(sale_date,'DD'));
		
		--Generate a weighted feedback score
		random_feedback = RANDOM();
		feedback_score = feedback_id FROM "table-load-base"."Feedback_Likelihood" WHERE weighting_rsum >= random_feedback ORDER BY feedback_id LIMIT 1;
		
		--Push into the Sales Header
		VALUES (1,
				CAST(RANDOM() * customer_total + 1 AS INT),
				sale_date_id,
				feedback_score,
				sale_date
				);
		
		--Generate a random number of transactions for this Sales Header
		transaction_no = sale_id FROM "sequel-mart-schema"."Sales_Header" ORDER BY sale_id DESC LIMIT 1;
		
		
		--Generate a set of products purchased by the customer in this transaction
		transaction_lines = CAST(RANDOM() * 20 + 1 AS INT);
		FOR j IN 1..transaction_lines LOOP
			
			items_sold = FLOOR(RANDOM() * 10 + 0.11);
			IF items_sold = 0 THEN
				items_sold = 1;
			END IF;
			
			--Generate a random product weighted by popularity & get price & cost
			random_product_popularity = FLOOR(RANDOM() * 70 + 16);
			product_line = product_id FROM "sequel-mart-schema"."Products" WHERE popularity >= random_product_popularity ORDER BY RANDOM() LIMIT 1;
			product_price = unit_sales_price FROM "sequel-mart-schema"."Products" WHERE product_id = product_line;
			product_cost = wholesale_price FROM "sequel-mart-schema"."Products" WHERE product_id = product_line;
			
			--Push into the Sales Details
			VALUES(transaction_no,
				   product_line,
				   items_sold,
				   items_sold * product_price,
				   items_sold * product_cost
			);
		END LOOP;

   	END LOOP;

    COMMIT;
END;
$$;


