--
-- Name: p_customers_generate(integer); Type: PROCEDURE; Schema: table-load-base; Owner: postgres
--

CREATE PROCEDURE "table-load-base".p_customers_generate(IN customers integer)
    LANGUAGE plpgsql
    AS $$
DECLARE first_name varchar(50);
DECLARE last_initial varchar(5);
BEGIN

	--Iterate through the number of customers specified above and return a random forename with a single letter 'surname'
	FOR i IN 1..customers LOOP
			SELECT CONCAT(customer_forename, ' ')
			FROM "table-load-base"."Customer_Names" 
			ORDER BY RANDOM() 
			LIMIT 1
		INTO first_name;
	  
			SELECT CONCAT(a.letter_name, '.', b.letter_name, '.', c.letter_name)
			FROM "table-load-base"."Alphabet" a
			CROSS JOIN "table-load-base"."Alphabet" b
			CROSS JOIN "table-load-base"."Alphabet" c
			WHERE a."popularity" >= FLOOR(RANDOM() * 10) 
			AND b."popularity" >= FLOOR(RANDOM() * 10)
			AND c."popularity" >= FLOOR(RANDOM() * 10)
			ORDER BY RANDOM() 
			LIMIT 1
		INTO last_initial;
	  
      	VALUES (CONCAT(first_name, last_initial), CURRENT_TIMESTAMP - ((RANDOM() * 230) * interval '1 day'));	  	

   END LOOP;

    COMMIT;
END;
$$;


