--
-- Name: v_Sales_Head_Detail; Type: VIEW; Schema: sequel-mart-schema; Owner: postgres
--

CREATE VIEW "sequel-mart-schema"."v_Sales_Head_Detail" AS
 SELECT sh.sale_id,
    sh.store_id,
    sh.customer_id,
    sh.feedback_score,
    sh.date_sale,
    sd.product_id,
    sd.items_sold,
    sd.revenue,
    sd.cost_of_sales,
    (sd.revenue - sd.cost_of_sales) AS gross_profit
   FROM ("sequel-mart-schema"."Sales_Header" sh
     JOIN "sequel-mart-schema"."Sales_Detail" sd ON ((sh.sale_id = sd.sale_id)));


ALTER VIEW "sequel-mart-schema"."v_Sales_Head_Detail" OWNER TO postgres;

--
-- Name: v_Sales_Head_Detail_Store_Product_Customer; Type: VIEW; Schema: sequel-mart-schema; Owner: postgres
--

CREATE VIEW "sequel-mart-schema"."v_Sales_Head_Detail_Store_Product_Customer" AS
 SELECT sh.sale_id,
    st.store_name,
    cu.customer_name,
    sh.feedback_score,
    sh.date_sale,
    pr.product_category,
    pr.product_item,
    pr.product_variety,
    pr.pack_size,
    pr.wholesale_price,
    pr.unit_sales_price,
    pr.inventory,
    sd.items_sold,
    sd.revenue,
    sd.cost_of_sales,
    (sd.revenue - sd.cost_of_sales) AS gross_profit
   FROM (((("sequel-mart-schema"."Sales_Header" sh
     JOIN "sequel-mart-schema"."Sales_Detail" sd ON ((sh.sale_id = sd.sale_id)))
     JOIN "sequel-mart-schema"."Stores" st ON ((st.store_id = sh.store_id)))
     JOIN "sequel-mart-schema"."Customers" cu ON ((cu.customer_id = sh.customer_id)))
     JOIN "sequel-mart-schema"."Products" pr ON ((pr.product_id = sd.product_id)));


ALTER VIEW "sequel-mart-schema"."v_Sales_Head_Detail_Store_Product_Customer" OWNER TO postgres;

